def ST(sid, off, hexs, fin=False):
    return {"type": "STREAM", "id": sid, "offset": off, "data_hex": hexs, "fin": fin}
def CR(off, hexs):
    return {"type": "CRYPTO", "offset": off, "data_hex": hexs}
def ACK(ranges):
    return {"type": "ACK", "ranges": ranges}
def RS(sid, fs):
    return {"type": "RESET_STREAM", "id": sid, "final_size": fs}
def SS(sid):
    return {"type": "STOP_SENDING", "id": sid}
def CL(app, code):
    return {"type": "CLOSE", "app": app, "code": code}
